import{_ as h,C as r,o as c,c as n,j as e,a,E as o,a5 as i}from"./chunks/framework.CyyS6Zdm.js";const g=JSON.parse('{"title":"固钉","description":"","frontmatter":{},"headers":[],"relativePath":"components/affix.md","filePath":"components/affix.md","lastUpdated":1787173379000}'),s={name:"components/affix.md"},f={id:"固钉",tabindex:"-1"};function p(b,t,x,u,m,q){const l=r("Badge"),d=r("XhDemo");return c(),n("div",null,[e("h1",f,[t[0]||(t[0]=a("固钉 ",-1)),o(l,{type:"info",text:"affix"}),t[1]||(t[1]=a()),t[2]||(t[2]=e("a",{class:"header-anchor",href:"#固钉","aria-label":'Permalink to "固钉 <Badge type="info" text="affix" />"'},"​",-1))]),t[3]||(t[3]=i('<p>滚过判定线就把内容钉在滚动容器可视区的边上；占位盒留在原位，页面不跳。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>表格的操作栏、表单的提交条、文章的目录，需要滚动时一直可达。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>元素从一开始就该钉住：直接写 <code>position: sticky</code>，不需要判定线。</li><li>要钉的是整块页面骨架（头、侧栏）：用<a href="./layout">布局</a>的吸顶开关。</li><li>需要滚到顶部的按钮：那是<a href="./back-top">回到顶部</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>占位盒留在原位：吸住的那一刻页面不会突然少一段高度。</li><li><code>offsetTop</code> 把判定线往下挪，钉住后也在同一位置留出这段高度；给了 <code>offsetBottom</code> 就改贴下边。</li><li>吸附状态会回调，默认插槽也把它透出来。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>滚过判定线就把内容钉在滚动容器可视区的上边；占位盒留在原位，页面不跳</p>',10)),o(d,{src:"affix/01-basic"}),t[4]||(t[4]=e("h3",{id:"让出吸顶栏",tabindex:"-1"},[a("让出吸顶栏 "),e("a",{class:"header-anchor",href:"#让出吸顶栏","aria-label":'Permalink to "让出吸顶栏"'},"​")],-1)),t[5]||(t[5]=e("p",null,"offset-top 把判定线往下挪，钉住后也在同一位置留出这段高度",-1)),o(d,{src:"affix/02-offset-top"}),t[6]||(t[6]=e("h3",{id:"贴下边",tabindex:"-1"},[a("贴下边 "),e("a",{class:"header-anchor",href:"#贴下边","aria-label":'Permalink to "贴下边"'},"​")],-1)),t[7]||(t[7]=e("p",null,"给了 offset-bottom 就改贴可视区的下边，判定线也换到下边",-1)),o(d,{src:"affix/03-offset-bottom"}),t[8]||(t[8]=e("h3",{id:"监听吸附状态",tabindex:"-1"},[a("监听吸附状态 "),e("a",{class:"header-anchor",href:"#监听吸附状态","aria-label":'Permalink to "监听吸附状态"'},"​")],-1)),t[9]||(t[9]=e("p",null,"affix-change 报吸住与松开；默认插槽也把 affixed 透出来",-1)),o(d,{src:"affix/04-affix-change"}),t[10]||(t[10]=i('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-affix&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhAffixContent</code> <code>XhAffixRoot</code></td></tr><tr><td>组合式函数</td><td><code>useAffix</code></td></tr><tr><td>状态机</td><td><code>affixMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/affix.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;affix&quot;</code>：<strong><code>root</code></strong> · <strong><code>content</code></strong></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>offsetTop</code></td><td><code>number</code></td><td></td><td>吸住后距滚动容器可视区上边的距离（px）。</td></tr><tr><td><code>offsetBottom</code></td><td><code>number</code></td><td></td><td>吸住后距滚动容器可视区下边的距离（px）；给了它就改贴下边。</td></tr><tr><td><code>onAffixChange</code></td><td><code>(details: AffixChangeDetails) =&gt; void</code></td><td></td><td>吸附状态变化回调。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>affix-change</code></td><td><code>AffixChangeDetails</code></td><td>吸附状态变化；detail 为 <code>{ affixed: boolean }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhAffixRoot</code></td><td><code>default</code></td><td><code>AffixRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>released</code> · <code>affixed</code></p><p><strong>事件</strong>：<code>SCROLL.RESOLVE</code></p><p><strong>判据</strong>：<code>shouldAffix</code> · <code>shouldRelease</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useAffix</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>affixed</code></td><td><code>boolean</code></td><td>此刻是不是吸住了。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/affix.css</code> 按部件选择：<code>[data-scope=&quot;affix&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>content</code></td><td><code>data-affixed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-affix-layer</code></p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>与<a href="./anchor">锚点</a>配合做吸顶目录；与<a href="./toolbar">工具栏</a>配合做吸顶操作条。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>页面已有吸顶栏时把栏高填进 <code>offsetTop</code>，否则会两层叠在一起。</li><li>钉住后给一点视觉变化（阴影或描边），让用户知道它已经脱离了原位。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>一屏里钉住多个条：可视高度被吃光，正文只剩一条缝。</li><li>在移动端钉住高条：小屏上这块面积很贵。</li></ul>',38))])}const k=h(s,[["render",p]]);export{g as __pageData,k as default};
